    fn konst(e: &Ex) -> bool {
        match e {
            Ex::Int(_) | Ex::Float(_) | Ex::Str(_) | Ex::NoneV | Ex::True | Ex::False | Ex::Ellipsis => true,
            Ex::Unary("-", x) => matches!(x.as_ref(), Ex::Int(_) | Ex::Float(_)),
            Ex::Tuple(xs) => xs.iter().all(konst),
            _ => false,
        }
